create table if not exists public.equipment_families (
 id uuid primary key default gen_random_uuid(), family_code text not null unique, name text not null,
 discipline text not null, description text, common_inspection_activities text[] not null default '{}',
 common_finding_categories text[] not null default '{}', common_test_milestones text[] not null default '{}',
 common_document_requirements text[] not null default '{}', created_at timestamptz not null default now()
);

on conflict(family_code) do nothing;

alter table public.assets add column if not exists equipment_family_code text references public.equipment_families(family_code);
alter table public.assets add column if not exists model_number text;
alter table public.assets add column if not exists factory_location text;
alter table public.assets add column if not exists commodity_description text;
alter table public.inspection_reports add column if not exists equipment_family_code text references public.equipment_families(family_code);
